namespace FileCompass {
 internal sealed partial class QuickPreviewPane {
  sealed class PreviewChoice:INotifyPropertyChanged {internal Entry Entry;ImageSource image;public string Caption{get{return Path.GetFileName(Entry.FullPath);}}public string PathLabel{get{return Entry.FullPath;}}public bool Thumbnail{get;set;}public ImageSource Image{get{return image;}set{image=value;if(PropertyChanged!=null){PropertyChanged(this,new PropertyChangedEventArgs("Image"));PropertyChanged(this,new PropertyChangedEventArgs("Thumbnail"));}}}public event PropertyChangedEventHandler PropertyChanged;}
  readonly ListBox selectionStrip=new ListBox{BorderThickness=new Thickness(0),Padding=new Thickness(0,0,0,10),Background=Brushes.Transparent,SelectionMode=SelectionMode.Single};
  readonly Border selectionFrame=new Border{Tag="panel-preview-carousel",Visibility=Visibility.Collapsed,Background=CompactTheme.ThemeBrush("#ECF3FA"),BorderBrush=CompactTheme.Line,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(6),Padding=new Thickness(6),Margin=new Thickness(0,5,0,7)};
  readonly TextBlock selectionCount=new TextBlock{Foreground=FluentTheme.Muted,FontSize=11,Margin=new Thickness(2,0,0,4)};
  Entry[] selectionFiles=new Entry[0];string selectionContext="";Action<Entry> openSelection;bool changingSelection,localThumbnails;int selectionGeneration;
  internal int SelectionCount{get{return selectionFiles.Length;}}internal int SelectedPreviewIndex{get{return selectionStrip.SelectedIndex;}}internal string SelectedPreviewPath{get{return selectionStrip.SelectedIndex<0?null:selectionFiles[selectionStrip.SelectedIndex].FullPath;}}
  internal bool SelectionMatches(Entry[] entries,string context){return selectionContext==context&&selectionFiles.Select(x=>x.FullPath).SequenceEqual(entries.Select(x=>x.FullPath));}
  bool carouselExpanded;Button carouselToggle;
  internal void SetCarouselExpanded(bool expanded){carouselExpanded=expanded;UpdateCarousel();}
  void UpdateCarousel(){if(carouselToggle==null)return;selectionFrame.Visibility=carouselExpanded&&selectionFiles.Length>0?Visibility.Visible:Visibility.Collapsed;carouselToggle.Visibility=selectionFiles.Length>0?Visibility.Visible:Visibility.Collapsed;var label=new StackPanel{Orientation=Orientation.Horizontal};label.Children.Add(new System.Windows.Shapes.Path{Data=Geometry.Parse(carouselExpanded?"M0,5 L5,0 L10,5":"M0,0 L5,5 L10,0"),Stroke=FluentTheme.Accent,StrokeThickness=1.3,Width=10,Height=6,Margin=new Thickness(0,0,7,0),VerticalAlignment=VerticalAlignment.Center});label.Children.Add(new TextBlock{Text=L.Text(carouselExpanded?"action.less":"action.more"),VerticalAlignment=VerticalAlignment.Center});carouselToggle.Content=label;}
  static ScrollViewer CarouselScroll(DependencyObject root){var viewer=root as ScrollViewer;if(viewer!=null)return viewer;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var found=CarouselScroll(VisualTreeHelper.GetChild(root,i));if(found!=null)return found;}return null;}
  void InitializeSelectionStrip(DockPanel body,bool compact){
   var stack=new StackPanel();stack.Children.Add(selectionCount);stack.Children.Add(selectionStrip);selectionFrame.Child=stack;var hostPanel=new StackPanel();carouselToggle=CopyUi.Button("",delegate{SetCarouselExpanded(!carouselExpanded);});carouselToggle.HorizontalAlignment=HorizontalAlignment.Left;carouselToggle.Margin=new Thickness(0,3,0,3);System.Windows.Automation.AutomationProperties.SetAutomationId(carouselToggle,"PreviewCarousel");hostPanel.Children.Add(selectionFrame);DockPanel.SetDock(hostPanel,Dock.Bottom);body.Children.Add(hostPanel);UpdateCarousel();
   ScrollViewer.SetHorizontalScrollBarVisibility(selectionStrip,ScrollBarVisibility.Hidden);ScrollViewer.SetVerticalScrollBarVisibility(selectionStrip,ScrollBarVisibility.Disabled);VirtualizingPanel.SetIsVirtualizing(selectionStrip,true);VirtualizingPanel.SetVirtualizationMode(selectionStrip,VirtualizationMode.Recycling);ScrollViewer.SetCanContentScroll(selectionStrip,true);
   var host=new FrameworkElementFactory(typeof(VirtualizingStackPanel));host.SetValue(VirtualizingStackPanel.OrientationProperty,Orientation.Horizontal);selectionStrip.ItemsPanel=new ItemsPanelTemplate(host);
   var row=new FrameworkElementFactory(typeof(StackPanel));row.SetValue(FrameworkElement.WidthProperty,100.0);row.SetBinding(FrameworkElement.ToolTipProperty,new Binding("PathLabel"));var icon=new FrameworkElementFactory(typeof(Image));icon.SetValue(Image.StretchProperty,Stretch.Uniform);icon.SetBinding(Image.SourceProperty,new Binding("Image"));icon.AddHandler(FrameworkElement.LoadedEvent,new RoutedEventHandler(async delegate(object sender,RoutedEventArgs args){var element=(Image)sender;var item=element.DataContext as PreviewChoice;int generation=selectionGeneration;if(!localThumbnails||item==null||FileViewers.Kind(item.Entry.FullPath)!="image")return;var thumbnail=await Task.Run(()=>SelectionThumbnail(item.Entry.FullPath));if(generation==selectionGeneration&&thumbnail!=null){item.Thumbnail=true;item.Image=thumbnail;}}));var imageStyle=new Style(typeof(Image));imageStyle.Setters.Add(new Setter(FrameworkElement.WidthProperty,22.0));imageStyle.Setters.Add(new Setter(FrameworkElement.HeightProperty,22.0));var thumbnailTrigger=new DataTrigger{Binding=new Binding("Thumbnail"),Value=true};thumbnailTrigger.Setters.Add(new Setter(FrameworkElement.WidthProperty,100.0));thumbnailTrigger.Setters.Add(new Setter(FrameworkElement.HeightProperty,compact?28.0:58.0));imageStyle.Triggers.Add(thumbnailTrigger);icon.SetValue(FrameworkElement.StyleProperty,imageStyle);icon.SetValue(Image.StretchDirectionProperty,StretchDirection.DownOnly);var imageSlot=new FrameworkElementFactory(typeof(Border));imageSlot.SetValue(FrameworkElement.HeightProperty,compact?28.0:58.0);imageSlot.AppendChild(icon);row.AppendChild(imageSlot);var name=new FrameworkElementFactory(typeof(TextBlock));name.SetBinding(TextBlock.TextProperty,new Binding("Caption"));name.SetValue(TextBlock.TextTrimmingProperty,TextTrimming.CharacterEllipsis);name.SetValue(TextBlock.FontSizeProperty,11.0);name.SetValue(TextBlock.TextAlignmentProperty,TextAlignment.Center);row.AppendChild(name);selectionStrip.ItemTemplate=new DataTemplate{VisualTree=row};
   var style=new Style(typeof(ListBoxItem));style.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(5)));style.Setters.Add(new Setter(FrameworkElement.MarginProperty,new Thickness(0,0,5,0)));style.Setters.Add(new Setter(Control.BackgroundProperty,CompactTheme.WhiteSurface));style.Setters.Add(new Setter(Control.BorderBrushProperty,CompactTheme.Line));style.Setters.Add(new Setter(Control.TemplateProperty,(ControlTemplate)System.Windows.Markup.XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='ListBoxItem'><Border Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='1' CornerRadius='4' Padding='{TemplateBinding Padding}'><ContentPresenter/></Border></ControlTemplate>")));var selected=new Trigger{Property=ListBoxItem.IsSelectedProperty,Value=true};selected.Setters.Add(new Setter(Control.BackgroundProperty,CompactTheme.ActivePath));selected.Setters.Add(new Setter(Control.BorderBrushProperty,FluentTheme.Accent));style.Triggers.Add(selected);selectionStrip.ItemContainerStyle=style;
   selectionStrip.PreviewMouseWheel+=delegate(object sender,MouseWheelEventArgs args){var scroll=CarouselScroll(selectionStrip);if(scroll!=null&&scroll.ScrollableWidth>0){scroll.ScrollToHorizontalOffset(scroll.HorizontalOffset-Math.Sign(args.Delta));args.Handled=true;}};
   selectionStrip.SelectionChanged+=delegate{if(!changingSelection)OpenSelectionItem();};selectionStrip.PreviewKeyDown+=delegate(object sender,KeyEventArgs args){if(args.Key==Key.Left||args.Key==Key.Right){SelectPreviewIndex(selectionStrip.SelectedIndex+(args.Key==Key.Right?1:-1));args.Handled=true;}};
  }
  static ImageSource SelectionThumbnail(string path){try{var image=new BitmapImage();using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.DecodePixelWidth=96;image.StreamSource=stream;image.EndInit();}image.Freeze();return image;}catch{return null;}}
  internal bool UpdatingSelection {get;private set;}
  internal void SetSelection(Entry[] entries,string context,Action<Entry> open,bool thumbnails,string preferred=null){UpdatingSelection=true;try{SetSelectionCore(entries,context,open,thumbnails,preferred);}finally{UpdatingSelection=false;}}
  void SetSelectionCore(Entry[] entries,string context,Action<Entry> open,bool thumbnails,string preferred){
   openSelection=open;localThumbnails=thumbnails;if(SelectionMatches(entries,context)){if(preferred!=null){int selected=Array.FindIndex(entries,x=>x.FullPath==preferred);if(selected>=0)SelectPreviewIndex(selected);}if(thumbnails&&SelectedPreviewIndex>=0)open(selectionFiles[SelectedPreviewIndex]);return;}
   string previous=preferred??SelectedPreviewPath;selectionGeneration++;selectionFiles=entries;selectionContext=context;changingSelection=true;try{selectionStrip.ItemsSource=entries.Select(x=>new PreviewChoice{Entry=x,Image=x.Icon}).ToArray();int index=Array.FindIndex(entries,x=>x.FullPath==previous);selectionStrip.SelectedIndex=entries.Length==0?-1:Math.Max(0,index);}finally{changingSelection=false;}UpdateCarousel();OpenSelectionItem();
  }
  internal void SelectPreviewIndex(int index){if(selectionFiles.Length==0)return;int next=Math.Max(0,Math.Min(selectionFiles.Length-1,index));if(selectionStrip.SelectedIndex==next)OpenSelectionItem();else selectionStrip.SelectedIndex=next;if(selectionStrip.SelectedItem!=null)selectionStrip.ScrollIntoView(selectionStrip.SelectedItem);}
  void OpenSelectionItem(){int index=SelectedPreviewIndex;if(index<0||index>=selectionFiles.Length)return;selectionCount.Text=L.Text("preview.files")+" · "+(index+1)+" / "+selectionFiles.Length;selectionFrame.ToolTip=L.Text("preview.selectionKeysHelp");if(openSelection!=null)openSelection(selectionFiles[index]);}
  void ReleaseSelection(){selectionGeneration++;selectionFiles=new Entry[0];selectionStrip.ItemsSource=null;openSelection=null;UpdateCarousel();}
 }
 public partial class FilePanel {
  internal event Action PreviewSelectionChanged;
  internal Entry[] PreviewEntries(){var marked=List.Items.Cast<Entry>().Where(x=>x.IsMarked&&!x.IsDirectory&&!x.IsParent).ToArray();if(marked.Length>0)return marked;var currentEntry=List.SelectedItem as Entry;if(currentEntry!=null&&!currentEntry.IsParent&&!currentEntry.IsDirectory&&!CanPreview(currentEntry.FullPath))return new[]{currentEntry};return List.Items.Cast<Entry>().Where(x=>!x.IsDirectory&&!x.IsParent&&CanPreview(x.FullPath)).ToArray();}
  static bool IsPreviewText(string path){return new[]{".txt",".log",".md",".markdown",".csv",".tsv",".json",".xml",".yaml",".yml",".ini",".cfg",".conf",".config",".cs",".cpp",".c",".h",".hpp",".js",".ts",".jsx",".tsx",".css",".html",".htm",".sql",".py",".ps1",".bat",".cmd",".sh",".vb",".resx",".xaml",".toml",".srt",".vtt",".svg",".rtf"}.Contains(Path.GetExtension(path).ToLowerInvariant());}
  internal static bool CanPreview(string path){return FileViewers.Kind(path)=="image"||IsPreviewText(path)||FileViewers.IsVideo(path)||DocumentPreview.Supports(path)||ArchiveEngine.Recognized(path);}
  internal string PreviewContext{get{return IsRemote?"remote:"+Remote.Profile.Id:IsArchive?"archive:"+Archive.FilePath:IsExt?"ext":"local";}}
  internal void SelectPreviewCursor(Entry entry){
   var actual=List.Items.Cast<Entry>().FirstOrDefault(x=>String.Equals(x.FullPath,entry.FullPath,StringComparison.OrdinalIgnoreCase));if(actual==null||Object.ReferenceEquals(List.SelectedItem,actual))return;
   bool previous=synchronizingSelection;synchronizingSelection=true;try{List.SelectedItem=actual;if(windowsSelection)foreach(var marked in List.Items.Cast<Entry>().Where(x=>x.IsMarked&&!x.IsParent&&x!=actual))if(!List.SelectedItems.Contains(marked))List.SelectedItems.Add(marked);List.ScrollIntoView(actual);}finally{synchronizingSelection=previous;}
  }
  internal void PreviewEntry(QuickPreviewPane pane,Entry entry){if(IsArchive)pane.ShowArchiveFile(Archive,entry.FullPath);else if(IsExt)pane.ShowExtFile(entry.FullPath);else if(IsRemote){if(Remote.Profile.Protocol==NetworkProtocol.FTP||Remote.Profile.Protocol==NetworkProtocol.SFTP)pane.ShowRemoteFile(entry.FullPath,Remote,entry.Bytes+"|"+entry.ModifiedTime.Ticks);else pane.ShowMessage(L.Text("remotePreview.ftpSftpRequired"));}else pane.ShowFile(entry.FullPath,true);}
 }
